frappe.ui.form.on("Purchase Order", {

    supplier: function(frm) {

        if (!frm.doc.supplier) return;

        frappe.db.get_value(

            "Supplier",

            frm.doc.supplier,

            ["tax_category"]

        ).then(r => {

            if (!r.message) return;

            // Set Tax Category

            if (r.message.tax_category) {

                frm.set_value("tax_category", r.message.tax_category);

            }

            // Fetch Taxes Template based on Tax Category

            frappe.db.get_value(

                "Purchase Taxes and Charges Template",

                {

                    tax_category: r.message.tax_category,

                    company: frm.doc.company

                },

                "name"

            ).then(t => {

                if (t.message) {

                    frm.set_value("taxes_and_charges", t.message.name);

                }

            });

        });

    }

});

frappe.ui.form.on("Purchase Receipt Item", {

    imei_track: function(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        if (!row.imei_track) return;

        if (!row.qty || row.qty <= 0) {
            frappe.msgprint("Enter Qty first");
            frappe.model.set_value(cdt, cdn, "imei_track", 0);
            return;
        }

        open_imei_dialog(frm, row);

    }

});


function open_imei_dialog(frm, item_row) {

    let data = [];

    for (let i = 0; i < item_row.qty; i++) {
        data.push({
            item_code: item_row.item_code,
            imei_number: ""
        });
    }

    let d = new frappe.ui.Dialog({

        title: "IMEI Entry",

        fields: [
            {
                fieldname: "imei_table",
                fieldtype: "Table",
                label: "IMEI List",
                in_place_edit: true,
                data: data,

                fields: [
                    {
                        fieldtype: "Data",
                        fieldname: "item_code",
                        label: "Item Code",
                        read_only: 1,
                        in_list_view: 1
                    },
                    {
                        fieldtype: "Data",
                        fieldname: "imei_number",
                        label: "IMEI Number",
                        reqd: 1,
                        in_list_view: 1
                    }
                ]
            }
        ],

        primary_action_label: "Save",

        primary_action(values) {

            if (!values.imei_table) return;

            // clear existing rows
            frm.clear_table("custom_imei_track");

            values.imei_table.forEach(function(d){

                let child = frm.add_child("custom_imei_track");

                child.item_code = d.item_code;
                child.imei_number = d.imei_number;

            });

            frm.refresh_field("custom_imei_track");

            frappe.msgprint("IMEI numbers added");

            d.hide();

        }

    });

    d.show();

}

frappe.listview_settings['Buyback Price Master'] = {
    onload(listview) {

        if (listview.buttons_added) return;
        listview.buttons_added = true;

        // Download button
        listview.page.add_inner_button('Buyback Price Import', () => {
            window.open('/api/method/buyback.api.download_buyback_template');
        });

        // Upload button
        listview.page.add_inner_button('Upload Price', () => {

            new frappe.ui.FileUploader({
                allow_multiple: false,
                on_success(file) {

                    frappe.call({
                        method: "buyback.api.upload_buyback_csv",
                        args: { file_url: file.file_url },
                        callback: () => {
                            frappe.msgprint("Upload complete");
                            listview.refresh();
                        }
                    });

                }
            });

        });

    }
};

frappe.ui.form.on('Buyback Request', {
    refresh(frm) {
        apply_mode(frm);
    },
    mode(frm) {
        apply_mode(frm);
    }
});

function apply_mode(frm) {

    let is_buyback = frm.doc.mode === "BuyBack";

    frm.toggle_display("buyback_section", is_buyback);
    frm.toggle_display("diagnosis_section", !is_buyback);

    frm.dashboard.clear_headline();
    frm.dashboard.set_headline(
        is_buyback ? "BuyBack Mode Active" : "Diagnosis Mode Active"
    );
}

frappe.ui.form.on('Buyback Request', {
    refresh(frm) {
        if (frm.is_new()) calc_price(frm);
    },

    item_id: calc_price,
    usage_key: calc_price,
    grade: calc_price
});

function calc_price(frm) {

    // stop if fields missing
    if (!frm.doc.item_id || !frm.doc.usage_key || !frm.doc.grade) {
        frm.set_value('buyback_price', 0);
        frm.set_value('final_buyback_amount', 0);
        frm.set_value('cash_notes', 0);
        return;
    }

    // build dynamic field name
    let key = `${frm.doc.grade}_grade_${frm.doc.usage_key}`;
    console.log("PRICE KEY →", key);


    frappe.db.get_doc('Buyback Price Master', frm.doc.item_id)
        .then(doc => {

            let price = doc[key] || 0;
            console.log("FETCHED PRICE →", price);

            frm.set_value('buyback_price', price);
            frm.set_value('final_buyback_amount', price);
            frm.set_value('cash_notes', price);

        })
        .catch(err => {
            console.error("Price fetch error:", err);
            frm.set_value('buyback_price', 0);
            frm.set_value('final_buyback_amount', 0);
            frm.set_value('cash_notes', 0);
        });
}

frappe.ui.form.on('Buyback Request', {
    refresh: function(frm) {

        if (frm.is_new()) {
            frm.set_value('buyback_request_staff', frappe.session.user);
        }
    }
});

frappe.ui.form.on('Buyback Request', {

    refresh(frm) {
        show_preview(frm);
    },

    customer_image(frm) {
        show_preview(frm);
    }
});

function show_preview(frm) {

    if (!frm.doc.customer_image) {
        frm.set_value('customer_image_preview', '');
        return;
    }

    let url = window.location.origin + frm.doc.customer_image;

    frm.set_value('customer_image_preview', url);
}

frappe.ui.form.on('Buyback Request', {
    payment_mode: function(frm) {
        payment_ui(frm);
    },
    refresh: function(frm) {
        payment_ui(frm);
    }
});

function payment_ui(frm) {

    // hide everything first
    frm.toggle_display([
        'cash_notes',
        'account_holder_name',
        'branch',
        'bank_name',
        'ifsc_code',
        'upi_id',
         'account_no',
        'transaction_proof'
    ], false);

    // always show amount
    frm.toggle_display('final_buyback_amount', true);

    if (!frm.doc.payment_mode) return;

    frappe.db.get_doc('Payment Method Master', frm.doc.payment_mode)
        .then(doc => {

            frm.set_value('payment_mode_name', doc.payment_method);

            // CASH
            if (doc.payment_method === "cash") {
                frm.toggle_display('cash_notes', true);
            }

            // BANK
            else if (doc.payment_method === "bank transfer") {
                frm.toggle_display([
                    'account_holder_name',
                    'branch',
                    'bank_name',
                    'ifsc_code',
                     'account_no',
                     'transaction_proof'
                ], true);
            }

            // UPI
            else if (doc.payment_method === "upi") {
                frm.toggle_display([
                    'upi_id',
                    'transaction_proof'
                ], true);
            }

        });
}

frappe.ui.form.on('Buyback Request', {
    refresh: function(frm) {
        toggle_no_deal(frm);
    },

    deal_status: function(frm) {
        toggle_no_deal(frm);
    }
});

function toggle_no_deal(frm) {
    if (frm.doc.deal_status === "No Deal") {
        frm.set_df_property('no_deal_reason', 'hidden', 0);
        frm.set_df_property('no_deal_reason', 'reqd', 1);
    } else {
        frm.set_df_property('no_deal_reason', 'hidden', 1);
        frm.set_df_property('no_deal_reason', 'reqd', 0);
        frm.set_value('no_deal_reason', '');
    }
}

frappe.ui.form.on('Buyback Request', {
    refresh(frm) {
        bind_integer_fields(frm);
    }
});

function bind_integer_fields(frm) {


    const integer_fields = ['mobile_no', 'pincode', 'imei'];

    integer_fields.forEach(fieldname => {

        const field = frm.fields_dict[fieldname];
        if (!field || !field.$input) return;

        const input = field.$input;

        // remove previous bindings
        input.off('.numeric');


        input.on('keypress.numeric', function (e) {

            const allowedKeys = [
                "Backspace", "Delete", "Tab",
                "ArrowLeft", "ArrowRight",
                "Home", "End"
            ];

            if (e.ctrlKey || e.metaKey || allowedKeys.includes(e.key)) {
                return;
            }

            if (!/^[0-9]$/.test(e.key)) {
                e.preventDefault();
            }
        });

            input.on('paste.numeric', function (e) {
            const pasted = (e.originalEvent || e).clipboardData.getData('text');
            if (!/^\d+$/.test(pasted)) {
                e.preventDefault();
            }
        });


        input.on('input.numeric', function () {
            this.value = this.value.replace(/\D/g, '');
        });
    });
}

frappe.ui.form.on('Buyback Price Master', {
    refresh(frm) {
        bind_integer_only(frm);
    }
});

function bind_integer_only(frm) {


    const integer_fields = ["buyback_price_id"];

    integer_fields.forEach(fieldname => {

        let field = frm.fields_dict[fieldname];
        if (!field || !field.$input) return;

        let input = field.$input;

        // remove previous binding
        input.off('keypress.numeric');

        input.on('keypress.numeric', function (e) {

            const allowedKeys = [
                "Backspace", "Delete", "Tab",
                "ArrowLeft", "ArrowRight",
                "Home", "End"
            ];

            // allow navigation + shortcuts
            if (e.ctrlKey || e.metaKey || allowedKeys.includes(e.key)) {
                return;
            }

            // allow digits only
            if (!/^[0-9]$/.test(e.key)) {
                e.preventDefault();
            }
        });
    });
}

frappe.ui.form.on("Sales Order", {

    refresh: function(frm) {

        // Add new options to Order Type dropdown
        frm.set_df_property("order_type", "options", [
            "Sales",
            "Maintenance",
            "Shopping Cart",
            "Direct Sales",
            "Credit Sales",
            "Finance Sales",
            "Online Sales",
            "Supplier Sales",
            "Free Sales"
        ].join("\n"));

    },

    order_type: function(frm) {

        let sales_type = frm.doc.order_type;

        // Reset required fields
        frm.set_df_property("payment_terms_template", "reqd", 0);

        if (!sales_type) return;

        if (sales_type === "Direct Sales") {

            frm.set_df_property("payment_terms_template", "reqd", 1);

            frappe.show_alert({
                message: "Direct Sales - Immediate payment required",
                indicator: "green"
            });

        }

        else if (sales_type === "Credit Sales") {

            frappe.show_alert({
                message: "Credit Sales - Payment will be collected later",
                indicator: "orange"
            });

        }

        else if (sales_type === "Finance Sales") {

            frm.set_df_property("payment_terms_template", "reqd", 1);

            frappe.show_alert({
                message: "Finance Sales - Payment handled by finance provider",
                indicator: "blue"
            });

        }

        else if (sales_type === "Online Sales") {

            frappe.show_alert({
                message: "Online Sales - Payment via online gateway",
                indicator: "green"
            });

        }

        else if (sales_type === "Supplier Sales") {

            frappe.show_alert({
                message: "Supplier Sales transaction",
                indicator: "purple"
            });

        }

        else if (sales_type === "Free Sales") {

            frm.set_value("payment_terms_template", "");

            frappe.msgprint("Free Sales - No payment required.");

        }

    }

});

frappe.ui.form.on("Sales Order Item", {
    custom_imei_no: function(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        if (!row.custom_imei_no) {
            return;
        }

        frappe.call({
            method: "ch_erp15.api.get_item_from_purchase_order_imei",
            args: {
                imei: row.custom_imei_no
            },
            callback: function(r) {

                if (r.message) {

                    frappe.model.set_value(
                        cdt,
                        cdn,
                        "item_code",
                        r.message.item_code
                    );

                    frappe.model.set_value(
                        cdt,
                        cdn,
                        "qty",
                        1
                    );

                    frm.refresh_field("items");

                } else {

                    frappe.msgprint("IMEI not found in Purchase Order");

                    frappe.model.set_value(
                        cdt,
                        cdn,
                        "custom_imei_no",
                        ""
                    );
                }

            }
        });

    }
});

function set_supplier_tax_details(frm) {

    if (!frm.doc.supplier) return;

    frappe.db.get_value(
        "Supplier",
        frm.doc.supplier,
        ["tax_category"]
    ).then(r => {

        if (!r.message) return;

        // Set Tax Category
        if (r.message.tax_category) {
            frm.set_value("tax_category", r.message.tax_category);
        }

        // Fetch Taxes Template based on Tax Category
        frappe.db.get_value(
            "Purchase Taxes and Charges Template",
            {
                tax_category: r.message.tax_category,
                company: frm.doc.company
            },
            "name"
        ).then(t => {

            if (t.message) {
                frm.set_value("taxes_and_charges", t.message.name);
            }

        });

    });
}

